-- +goose Up
-- +goose StatementBegin
-- Xero reference dataset for the demo organisation.
--
-- Imports the chart of accounts, contacts, coded bank transactions and bank
-- statement lines captured from the live Xero organisation "Demo Company
-- (Global)" (shortCode !!6Sp3) into organisation 6823b27b-c48f-4099-bb27-4202a4f496a2.
--
-- Source of every value: migrations/data/xero/{accounts,bank-accounts,
-- bank-transactions,statement-lines}.csv.  See docs/xero-reference/README.md
-- for how the capture was made and what it does not cover.  No figure in this
-- migration is estimated, rounded, averaged or invented; the one number that
-- is not a straight copy is the opening balance in section 6, and its
-- derivation is written out there.
--
-- Every statement is scoped to the one organisation; no other row is touched.
--
-- Ids are uuid_generate_v5() of a fixed key, so `down` then `up` restores the
-- same rows rather than merely the same counts.  The single exception is
-- gl_journals.journal_number, which comes from a sequence and therefore
-- advances on every re-run.

-- ---------------------------------------------------------------------------
-- 0. Clear what the demo organisation carries today.
--
-- The current chart is the seeded US chart from 00018, which gives different
-- meanings to the same codes (there 200 is Accounts Payable and 610 is
-- Accounts Receivable; in Xero's chart 200 is Sales and 610 is Accounts
-- Receivable).  Replacing it therefore cannot be done row by row -- the bank
-- data, the GL and the bank rules all reference those rows -- so the demo
-- organisation's bank/GL data is cleared first and re-created from the Xero
-- capture below.  The DOWN half puts every one of those rows back, with its
-- original id, so nothing here is a one-way door.
-- ---------------------------------------------------------------------------
DELETE FROM bank_statement_line_comments WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2';
DELETE FROM bank_reconcile_periods       WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2';
DELETE FROM bank_statement_lines         WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2';
DELETE FROM bank_statement_imports       WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2';

-- gl_journal_lines.account_id is ON DELETE RESTRICT, so the journals have to
-- go before the accounts they post to (their lines cascade with them).
DELETE FROM gl_journals    WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2';
DELETE FROM bank_transactions WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2';

-- bank_rules keep account ids inside their JSONB definition; leaving them
-- behind would point a rule at an account that no longer exists.
DELETE FROM bank_rules WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2';

-- Two kinds of reference onto accounts survive the DELETE below instead of
-- stopping it, and both would be damaged rather than removed:
--
--   * bank_transfers / batch_payments are ON DELETE RESTRICT -- the delete
--     would fail with a bare foreign-key error;
--   * invoice lines, payments, manual-journal lines and bank feed accounts are
--     ON DELETE SET NULL -- the delete would succeed and silently blank the
--     account those rows point at, which nothing here would put back.
--
-- None of them is populated in this database.  If that ever stops being true,
-- say so in a sentence and stop, rather than half-replacing the chart.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM bank_transfers
                WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2')
       OR EXISTS (SELECT 1 FROM batch_payments
                   WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2')
       OR EXISTS (SELECT 1 FROM payments
                   WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2')
       OR EXISTS (SELECT 1 FROM bank_feed_accounts
                   WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2')
       OR EXISTS (SELECT 1 FROM invoices i
                   WHERE i.organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2'
                     AND EXISTS (SELECT 1 FROM invoice_line_items li
                                  WHERE li.invoice_id = i.invoice_id
                                    AND (li.account_id IS NOT NULL OR li.account_code IS NOT NULL)))
       OR EXISTS (SELECT 1 FROM manual_journals mj
                   WHERE mj.organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2'
                     AND EXISTS (SELECT 1 FROM manual_journal_lines ml
                                  WHERE ml.manual_journal_id = mj.manual_journal_id))
    THEN
        RAISE EXCEPTION
            'demo organisation already has invoices, payments, manual journals, '
            'bank transfers or batch payments against this chart; the Xero chart '
            'cannot replace it without blanking those references';
    END IF;
END
$$;

-- 00018's tax rates (9.25%) are not Xero's; replace the set wholesale.
DELETE FROM accounts   WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2';
DELETE FROM tax_rates  WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2';

-- ---------------------------------------------------------------------------
-- 1. Tax rates -- the four rates accounts.csv and bank-transactions.csv name.
--
-- Xero gives each rate its own TaxType code, so the two income rates get
-- separate codes (OUTPUT / OUTPUT2): the account and bank-rule forms
-- de-duplicate their dropdown by TaxType and would otherwise hide one of them.
-- Percentages are read straight off the rate names in the CSVs.
-- ---------------------------------------------------------------------------
INSERT INTO tax_rates (tax_rate_id, organisation_id, name, tax_type, report_tax_type,
                       display_tax_rate, effective_rate) VALUES
    (uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/tax-rate/Tax Exempt (0%)'), '6823b27b-c48f-4099-bb27-4202a4f496a2', 'Tax Exempt (0%)', 'NONE', 'NONE', 0, 0),
