    (uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/tax-rate/Tax on Consulting (8.25%)'), '6823b27b-c48f-4099-bb27-4202a4f496a2', 'Tax on Consulting (8.25%)', 'OUTPUT', 'OUTPUT', 8.25, 8.25),
    (uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/tax-rate/Tax on Goods (8.75%)'), '6823b27b-c48f-4099-bb27-4202a4f496a2', 'Tax on Goods (8.75%)', 'OUTPUT2', 'OUTPUT2', 8.75, 8.75);

-- ---------------------------------------------------------------------------
-- 2. Chart of accounts -- all 58 rows of accounts.csv.
