-- ---------------------------------------------------------------------------
-- 2b. The two bank accounts, carrying the account numbers bank-accounts.csv
-- records verbatim.  Both are type BANK; bank_account_type is the flag the
-- bank-accounts screens read.
-- ---------------------------------------------------------------------------
UPDATE accounts a
   SET bank_account_number = v.number, bank_account_type = 'BANK'
  FROM (VALUES ('Business Bank Account', '090-8007-006543'), ('Business Savings Account', '121314-121314')) AS v(name, number)
 WHERE a.organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2' AND a.name = v.name;

-- Both updates must have found their account; say so if one did not.
DO $$
BEGIN
    IF (SELECT count(*) FROM accounts
         WHERE organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2' AND bank_account_number IS NOT NULL) <> 2 THEN
        RAISE EXCEPTION 'expected 2 bank accounts to carry an account number';
    END IF;
END
$$;

