-- ---------------------------------------------------------------------------
-- 4. The 48 coded bank transactions, their coded lines, and each one's posting
--    to the general ledger.
--
-- The posting reproduces internal/repository/gl.go::postBankTransactionJournal
-- on the same two tables it writes: one gl_journals row (source_type
-- BANKTRANSACTION, source_id the bank transaction, journal_date the
-- transaction date, reference the CSV reference) and two gl_journal_lines --
-- the bank leg on the account the money moved through, and the coded leg on
-- the account the CSV records, signed so the pair nets to zero
-- (net_amount > 0 debit, < 0 credit).
--
-- tax_amount is 0 on every coded line: the captured grid prints one gross
-- amount per transaction and no tax split, so splitting it would mean
-- inventing a figure.  tax_type still records the rate Xero coded, which is
-- what the account and the rate rows agree on.  With no tax amount
-- gl.go adds no tax leg, so no 820 leg appears here either.
--
-- One row -- 11 Aug 2026, Boom FM, INV-0013 -- is coded to two lines in Xero
-- ("Sales; Sales").  The capture holds the transaction total, not the per-line
-- amounts, so it lands as a single line on Sales rather than as an invented
-- 50/50 split.
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE xero_bank_tx (
    n            int,
    tx_date      date,
    contact_name text,
    description  text,
    reference    text,
    amount       numeric,
    direction    text,
    tax_type     text,
    account_code text
) ON COMMIT DROP;

