-- 4a. the transactions themselves
INSERT INTO bank_transactions (bank_transaction_id, organisation_id, contact_id,
                               bank_account_id, type, is_reconciled, date, reference,
                               currency_code, status, line_amount_types, sub_total,
                               total_tax, total)
SELECT uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/bank-transaction/' || s.n::text), '6823b27b-c48f-4099-bb27-4202a4f496a2',
       (SELECT c.contact_id FROM contacts c
         WHERE c.organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2' AND c.name = s.contact_name),
       (SELECT a.account_id FROM accounts a
         WHERE a.organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2' AND a.code = '090'),
       CASE s.direction WHEN 'out' THEN 'SPEND' ELSE 'RECEIVE' END,
       TRUE, s.tx_date, s.reference, 'USD', 'AUTHORISED', 'Exclusive',
       s.amount, 0, s.amount
  FROM xero_bank_tx s;

-- 4b. the coded line each transaction carries
INSERT INTO bank_transaction_line_items (line_item_id, bank_transaction_id, description,
                                         quantity, unit_amount, account_code, account_id,
                                         tax_type, tax_amount, line_amount)
SELECT uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/bank-transaction/' || s.n::text || '/line/1'), uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/bank-transaction/' || s.n::text), s.description, 1, s.amount, s.account_code,
       (SELECT a.account_id FROM accounts a
         WHERE a.organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2' AND a.code = s.account_code),
       s.tax_type, 0, s.amount
  FROM xero_bank_tx s;

-- 4c. one journal per transaction
INSERT INTO gl_journals (journal_id, organisation_id, reference, source_type, source_id,
                         journal_date)
SELECT uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/bank-transaction/' || s.n::text || '/journal'), '6823b27b-c48f-4099-bb27-4202a4f496a2', s.reference, 'BANKTRANSACTION', uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/bank-transaction/' || s.n::text), s.tx_date
  FROM xero_bank_tx s;

-- 4d. bank leg -- debited when the money came in, credited when it went out.
-- gl.go takes the unsigned total and multiplies by bankSign (-1 for a spend,
-- +1 for a receive); on the signed amounts kept here that is simply the amount
-- itself, which is why no CASE appears.
INSERT INTO gl_journal_lines (line_id, journal_id, account_id, description, tax_type,
                              tax_amount, net_amount, gross_amount)
SELECT uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/bank-transaction/' || s.n::text || '/gl/bank'), uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/bank-transaction/' || s.n::text || '/journal'), b.account_id, NULL, NULL, 0, s.amount, s.amount
  FROM xero_bank_tx s
  CROSS JOIN (SELECT a.account_id FROM accounts a
               WHERE a.organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2' AND a.code = '090') b;

-- 4e. coded leg -- the exact opposite of the bank leg, so the journal sums to
-- zero (gl.go's gross * -bankSign).
INSERT INTO gl_journal_lines (line_id, journal_id, account_id, description, tax_type,
                              tax_amount, net_amount, gross_amount)
SELECT uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/bank-transaction/' || s.n::text || '/gl/coded'), uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/bank-transaction/' || s.n::text || '/journal'), a.account_id, s.description, s.tax_type, 0,
       -s.amount, -s.amount
  FROM xero_bank_tx s
  JOIN accounts a ON a.organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2' AND a.code = s.account_code;

DROP TABLE xero_bank_tx;

-- ---------------------------------------------------------------------------
-- 5. The 101 statement lines from statement-lines.csv.
--
-- Xero's "reconciled" lines become IMPORTED (matched, so they stay out of the
-- reconcile inbox) and its 27 unreconciled lines become NEW (they are the
-- inbox).  They are deliberately NOT linked to the bank_transactions rows
-- above: the capture prints a payee ("Petrie McCloud") where the transaction
-- carries the contact ("Petrie McLoud Watson & Associates") and a date plus
-- amount match is ambiguous -- 21 Aug 2026 alone has four separate 541.25
-- receipts.  bank_transaction_id therefore stays NULL even on matched lines.
--
-- source is IMPORT (no bank feed connection is involved) and import_id stays
-- NULL (this is a captured dataset, not a batch a user uploaded).
-- provider_tx_id is NOT NULL in the schema, so it carries a per-line key --
-- the only value on these rows that is not Xero's own data.
--
-- All 101 rows sit on the Business Bank Account, because that is how the
-- capture has them: Xero shows no activity at all for Business Savings
-- Account (docs/xero-reference/README.md, notes 1 and 2), so nothing is
-- invented to fill it.
-- ---------------------------------------------------------------------------
