-- ---------------------------------------------------------------------------
-- 6. The bank account's opening balance.
--
-- The captured transactions are the tail of the account's history (11 Aug -
-- 11 Sep 2026); it was already carrying money before them.  Xero reports the
-- closing balance as 7,430.22 (accounts.csv ytd for 090 = bank-accounts.csv
-- balance_in_xero = Bank Summary closing = Balance Sheet Business Bank
-- Account), and the captured transactions move it by -1223.79, so the balance
-- it must already have carried is 7,430.22 - (-1223.79) = 8654.01.
-- Those three published figures are the whole derivation; nothing else is
-- assumed.
--
-- The contra account is 840 Historical Adjustment, the account Xero itself
-- uses for a conversion balance, and the date is the last day before the
-- financial year so it reads as an opening balance rather than as movement
-- inside FY2026.
-- ---------------------------------------------------------------------------
INSERT INTO gl_journals (journal_id, organisation_id, reference, source_type, source_id,
                         journal_date)
VALUES (uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/opening-balance/journal'), '6823b27b-c48f-4099-bb27-4202a4f496a2', 'Opening balance brought forward', 'MANUALJOURNAL', NULL,
        DATE '2025-12-31');

-- DR 090 / CR 840
INSERT INTO gl_journal_lines (line_id, journal_id, account_id, description, tax_type,
                              tax_amount, net_amount, gross_amount)
SELECT uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/opening-balance/' || v.code), uuid_generate_v5(uuid_ns_url(), 'goxero/xero-ref/opening-balance/journal'), a.account_id, 'Opening balance brought forward', NULL, 0,
       v.net, v.net
  FROM (VALUES ('090', 8654.01), ('840', -8654.01)) AS v(code, net)
  JOIN accounts a ON a.organisation_id = '6823b27b-c48f-4099-bb27-4202a4f496a2' AND a.code = v.code;
-- +goose StatementEnd

